INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-1', 1, 'Recursos', 'Recursos financieros, técnicos, humanos y de otra índole requeridos para coordinar y desarrollar el Sistema de Gestión de la Seguridad y Salud en el Trabajo (SG-SST)', 10, 1) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-2', 2, 'Gestión Integral del Sistema de Gestión de la Seguridad y Salud en el Trabajo', 'Política, objetivos, evaluación inicial, plan de trabajo anual y conservación de documentos', 15, 2) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-3', 3, 'Gestión de la Salud', 'Condiciones de salud en el trabajo, registro y reporte de condiciones de trabajo y de salud, mecanismos de vigilancia de las condiciones de salud de los trabajadores', 20, 3) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-4', 4, 'Gestión de Peligros y Riesgos', 'Identificación de peligros, evaluación y valoración de riesgos, medidas de prevención y control', 30, 4) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-5', 5, 'Gestión de Amenazas', 'Plan de prevención, preparación y respuesta ante emergencias', 10, 5) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-6', 6, 'Verificación del SG-SST', 'Gestión y resultados del SG-SST (auditoría y revisión por la alta dirección)', 5, 6) ON CONFLICT DO NOTHING;
INSERT INTO componentes_sst (id, numero, nombre, descripcion, peso_total, orden) VALUES ('comp-sst-7', 7, 'Mejoramiento', 'Acciones preventivas y correctivas con base en los resultados del SG-SST', 10, 7) ON CONFLICT DO NOTHING;
INSERT INTO estandares_sst (id, componente_id, numero_estandar, nombre, descripcion, marco_legal, puntaje_tipo1, puntaje_tipo2, puntaje_tipo3, puntaje_tipo4, criterios_verificacion, orden, activo) VALUES ('std-1.1.1', 'comp-sst-1', '1.1.1', 'Responsable del Sistema de Gestión de Seguridad y Salud en el Trabajo SG-SST', 'Asignar y comunicar a un responsable del SG-SST quien debe dar cuenta de manera periódica a la alta dirección de su funcionamiento y resultados.', 'Decreto 1072 de 2015, artículo 2.2.4.6.8, numeral 1', 5, 5, 5, 5, 'Documento que contenga la asignación y comunicación del responsable del SG-SST', 1, 1) ON CONFLICT DO NOTHING;
INSERT INTO estandares_sst (id, componente_id, numero_estandar, nombre, descripcion, marco_legal, puntaje_tipo1, puntaje_tipo2, puntaje_tipo3, puntaje_tipo4, criterios_verificacion, orden, activo) VALUES ('std-1.1.2', 'comp-sst-1', '1.1.2', 'Responsabilidades en el Sistema de Gestión de Seguridad y Salud en el Trabajo – SG-SST', 'Asignar responsabilidades específicas en Seguridad y Salud en el Trabajo (SST) a los distintos niveles de la organización.', 'Decreto 1072 de 2015, artículo 2.2.4.6.8, numeral 2', 5, 5, 5, 5, 'Documentos que contengan la asignación de responsabilidades específicas', 2, 1) ON CONFLICT DO NOTHING;
INSERT INTO estandares_sst (id, componente_id, numero_estandar, nombre, descripcion, marco_legal, puntaje_tipo1, puntaje_tipo2, puntaje_tipo3, puntaje_tipo4, criterios_verificacion, orden, activo) VALUES ('std-2.1.1', 'comp-sst-2', '2.1.1', 'Política del Sistema de Gestión de Seguridad y Salud en el Trabajo SG-SST firmada', 'Política de Seguridad y Salud en el Trabajo firmada, fechada y comunicada al COPASST/Vigía de SST.', 'Decreto 1072 de 2015, artículo 2.2.4.6.5', 10, 10, 10, 10, 'Documento escrito de la política firmada, fechada y comunicada', 3, 1) ON CONFLICT DO NOTHING;
INSERT INTO estandares_sst (id, componente_id, numero_estandar, nombre, descripcion, marco_legal, puntaje_tipo1, puntaje_tipo2, puntaje_tipo3, puntaje_tipo4, criterios_verificacion, orden, activo) VALUES ('std-3.1.1', 'comp-sst-3', '3.1.1', 'Evaluación Médica Ocupacional', 'Realizar evaluaciones médicas ocupacionales (ingreso, periódicas, retiro) acorde con la identificación de peligros.', 'Resolución 2346 de 2007, Decreto 1072 de 2015 art 2.2.4.6.24', 10, 10, 10, 10, 'Documentos de evaluaciones médicas ocupacionales y restricciones', 4, 1) ON CONFLICT DO NOTHING;
