INSERT INTO responsible_designations (id, company_id, worker_id, designation_date, position, responsibilities, signature_url, status, created_at, job_profile_id) VALUES ('6fdbeace-6e45-4de0-9853-b28f1d5bb41e', '58c0bc33-b87d-4f6f-9c6e-daa75e954fba', '5f95824c-393b-499b-916a-7d6b373f6fa2', '2025-10-18T00:00:00.000Z', 'Vigía de Seguridad y Salud', '{"1234567890-","Actuar como instrumento de vigilancia del cumplimiento del Sistema de Gestión de Seguridad y Salud en el Trabajo."}', '', 'activo', '2025-10-18T21:27:16.399Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO responsible_designations (id, company_id, worker_id, designation_date, position, responsibilities, signature_url, status, created_at, job_profile_id) VALUES ('5c957c6d-84bf-44b1-a1fb-e298c8592ba9', '58c0bc33-b87d-4f6f-9c6e-daa75e954fba', 'e523640e-1c45-4947-9bfc-8c5f90f63f11', '2025-10-19T00:00:00.000Z', 'Responsable del Plan de Emergencias', '{"Conformar, capacitar y dotar la brigada de emergencias de la empresa.","Realizar simulacros de evacuación periódicos y evaluar su efectividad.","Identificar amenazas, evaluar vulnerabilidades y analizar riesgos de la empresa.","Establecer los procedimientos de actuación antes, durante y después de una emergencia.","Coordinar con organismos de socorro (Bomberos, Cruz Roja, Defensa Civil) planes de ayuda mutua.","Verificar el funcionamiento y mantenimiento de equipos de emergencia (extintores, alarmas, botiquines, señalización).","Elaborar y actualizar planos de evacuación y puntos de encuentro.","Realizar inspecciones periódicas de las condiciones de seguridad de las instalaciones.","Mantener actualizada la información de contacto de personal de emergencias y organismos de socorro.","Diseñar, implementar y mantener actualizado el Plan de Prevención, Preparación y Respuesta ante Emergencias."}', '', 'activo', '2025-10-19T04:18:10.463Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO responsible_designations (id, company_id, worker_id, designation_date, position, responsibilities, signature_url, status, created_at, job_profile_id) VALUES ('68699928-a9cf-467c-9492-579947715aa7', '58c0bc33-b87d-4f6f-9c6e-daa75e954fba', '149763da-baf9-4391-8e0a-9526c30541c0', '2025-10-23T00:00:00.000Z', 'Secretario del COPASST', '{"Verificar la asistencia de los miembros del Comité a las reuniones programadas.","Tomar nota detallada de todos los temas tratados en cada reunión del COPASST.","Elaborar el acta de cada reunión y someterla a discusión y aprobación del Comité.","Llevar el archivo organizado de las actas y demás actividades desarrolladas por el comité.","Suministrar toda la información que requieran el empleador y los trabajadores sobre las actividades del COPASST.","Preparar los informes periódicos sobre la gestión del comité cuando sean solicitados.","Mantener actualizado el registro de asistencia a las reuniones del COPASST.","Garantizar la confidencialidad de la información sensible tratada en el comité.","Coordinar con el presidente la preparación de la agenda para cada reunión.","Custodiar los documentos, registros y archivo histórico del COPASST."}', '', 'activo', '2025-10-19T17:00:21.903Z', '4bf14e73-8d1a-45ad-9768-b8828db0e02b') ON CONFLICT DO NOTHING;
INSERT INTO responsible_designations (id, company_id, worker_id, designation_date, position, responsibilities, signature_url, status, created_at, job_profile_id) VALUES ('6b32bf33-76e1-4ab8-a080-6e00fd16e355', '58c0bc33-b87d-4f6f-9c6e-daa75e954fba', '5ebfcc81-2208-4e56-93ab-9b65d47fd014', '2025-10-20T00:00:00.000Z', 'Secretario del COPASST', '{"Verificar la asistencia de los miembros del Comité a las reuniones programadas.","Tomar nota detallada de todos los temas tratados en cada reunión del COPASST.","Elaborar el acta de cada reunión y someterla a discusión y aprobación del Comité.","Llevar el archivo organizado de las actas y demás actividades desarrolladas por el comité.","Suministrar toda la información que requieran el empleador y los trabajadores sobre las actividades del COPASST.","Preparar los informes periódicos sobre la gestión del comité cuando sean solicitados.","Mantener actualizado el registro de asistencia a las reuniones del COPASST.","Garantizar la confidencialidad de la información sensible tratada en el comité.","Coordinar con el presidente la preparación de la agenda para cada reunión.","Custodiar los documentos, registros y archivo histórico del COPASST."}', '', 'activo', '2025-10-20T07:42:18.067Z', '4bf14e73-8d1a-45ad-9768-b8828db0e02b') ON CONFLICT DO NOTHING;
